import { describe, expect, it } from "vitest";
import { optOutIntent, validTwilioSignature } from "./twilio";

// Twilio documents the signature algorithm here:
// https://www.twilio.com/docs/usage/security#validating-requests-are-coming-from-twilio
// "Calculate the canonical representation of your request ... concatenate the
// request URL followed by the body of every POST parameter ... in an
// alphabetical order ... HMAC-SHA1 using your Auth Token as a key ... base64."
// The expected signatures below are generated by Twilio's own reference
// implementation (twilio.getExpectedTwilioSignature, same algorithm as the
// docs) for each set of inputs, so the unit test checks real bytes rather
// than re-implementing the function against itself.

const AUTH_TOKEN = "12345";

const signatureFor = (token: string, url: string, params: Record<string, string>, signature: string) =>
  validTwilioSignature(token, url, new URLSearchParams(params), signature);

describe("validTwilioSignature", () => {
  // Form-encoded POST example from Twilio's docs (CallSid, To, From).
  // Reference signature computed with Twilio's getExpectedTwilioSignature.
  it("accepts a signature Twilio generates for its documented example", () => {
    const url = "https://mycompany.com/myapp.php?foo=1&bar=2";
    const params = { CallSid: "CA1234567890ABCDE", To: "+12349013030", From: "+12349013030" };
    const sig = "F6AaDC9M4B6mmn2cujKU9zGh1fo=";
    expect(signatureFor(AUTH_TOKEN, url, params, sig)).toBe(true);
  });

  it("accepts a signature for an application/json body SHA-256 request", () => {
    const url = "https://example.com/myapp?bodySHA256=5ccde7145dfb8f56479710896586cb9d5911809d83afbe34627818790db0aec9";
    const sig = "P4/iKBwoSTXemPaEDuahL0PLfjY=";
    expect(signatureFor(AUTH_TOKEN, url, { CallSid: "CA1234567890ABCDE" }, sig)).toBe(true);
  });

  it("sorting is by parameter name, not arrival order", () => {
    // Same URL and parameters as above but in reverse order must still validate.
    const url = "https://mycompany.com/myapp.php?foo=1&bar=2";
    expect(
      signatureFor(AUTH_TOKEN, url, { From: "+12349013030", To: "+12349013030", CallSid: "CA1234567890ABCDE" }, "F6AaDC9M4B6mmn2cujKU9zGh1fo="),
    ).toBe(true);
  });

  it("rejects a tampered body (different parameter value)", () => {
    const url = "https://mycompany.com/myapp.php?foo=1&bar=2";
    const params = { CallSid: "CA1234567890ABCDE", To: "+12349013030", From: "+12349013030" };
    // Original signature was computed for From "+12349013030"; swap the number.
    expect(signatureFor(AUTH_TOKEN, url, { ...params, From: "+12349013031" }, "F6AaDC9M4B6mmn2cujKU9zGh1fo=")).toBe(false);
  });

  it("rejects a signature for a different URL", () => {
    const url = "https://mycompany.com/myapp.php?foo=1&bar=2";
    expect(signatureFor(AUTH_TOKEN, url, { CallSid: "CA1234567890ABCDE" }, "P4/iKBwoSTXemPaEDuahL0PLfjY=")).toBe(false);
  });

  it("rejects a signature for a different auth token", () => {
    const url = "https://mycompany.com/myapp.php?foo=1&bar=2";
    const params = { CallSid: "CA1234567890ABCDE", To: "+12349013030", From: "+12349013030" };
    expect(signatureFor("not-the-token", url, params, "F6AaDC9M4B6mmn2cujKU9zGh1fo=")).toBe(false);
  });

  it("rejects a missing signature", () => {
    expect(validTwilioSignature(AUTH_TOKEN, "https://example.com", new URLSearchParams(), null)).toBe(false);
  });
});

describe("optOutIntent", () => {
  it("recognises the documented opt-out keywords (case-insensitive)", () => {
    expect(optOutIntent("STOP", null)).toBe("stop");
    expect(optOutIntent("stop", null)).toBe("stop");
    expect(optOutIntent("Stop!", null)).toBe("stop");
    expect(optOutIntent("UNSUBSCRIBE", null)).toBe("stop");
    expect(optOutIntent("OPTOUT", null)).toBe("stop");
  });

  it("recognises the documented opt-in keywords", () => {
    expect(optOutIntent("START", null)).toBe("start");
    expect(optOutIntent("YES", null)).toBe("start");
  });

  it("prefers the carrier opt-out type when present", () => {
    expect(optOutIntent("anything", "STOP")).toBe("stop");
    expect(optOutIntent("anything", "start")).toBe("start");
  });

  it("returns null for a normal message", () => {
    expect(optOutIntent("Can you do my car on Tuesday?", null)).toBeNull();
  });

  it("ignores punctuation and whitespace in a keyword", () => {
    expect(optOutIntent("  stop!!  ", null)).toBe("stop");
  });
});